import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates an optimized image generation prompt based on product data and optional template.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = getAI();
  try {
    const parts: any[] = [];
    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({ inlineData: { mimeType: data.mimeType, data: base64Data } });
    }

    const templateInstruction = data.description ? `Base your prompt on this visual style/instruction (provided in Vietnamese): "${data.description}".` : "";

    const promptInput = `
    Role: Expert AI Prompt Engineer for pharmaceutical advertising.
    Task: Write a detailed English text-to-image prompt for a high-quality pharmaceutical poster.

    Product Info:
    - Name: ${data.name}
    - Dosage: ${data.dosage}
    - Usage: ${data.usage}
    - Manufacturer: ${data.manufacturer}
    - Special Price from IDECO: ${data.idecoPrice}

    Layout: ${data.aspectRatio === 'vertical' ? 'Vertical 3:4 poster' : 'Horizontal 16:9 banner'}.

    Instruction details:
    ${templateInstruction}

    Mandatory Elements:
    1. If the instruction mentions a "Dược sĩ Nữ" (female pharmacist), describe a beautiful, professional pharmacist in a crisp white lab coat in a modern pharmacy.
    2. The product packaging (refer to the image provided) must be central and clearly visible.
    3. IMPORTANT: Highlight the price "${data.idecoPrice}" as a key feature of the poster (e.g., in a special badge or prominent area).
    4. Lighting: Cinematic medical studio lighting, bright and professional.
    5. Environment: High-end pharmacy or clean laboratory background.

    Output: Return ONLY the final detailed prompt string in English. Do not include any introductory or concluding text.
    `;
    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }],
    });
    return response.text || "";
  } catch (error) {
    throw error;
  }
};

/**
 * Xử lý hình ảnh: Xóa nền hoặc Tạo hộp 3D
 */
export const processImageWithAI = async (
  imageBase64: string, 
  mimeType: string, 
  task: 'remove_bg' | 'make_3d'
): Promise<string> => {
  const ai = getAI();
  const base64Data = imageBase64.split(',')[1];

  const prompts = {
    remove_bg: "Please remove the background of this pharmaceutical product perfectly. Output only the product on a pure white background. Keep all text and details on the package intact. Ensure high transparency awareness.",
    make_3d: "Transform this 2D pharmaceutical label or product photo into a high-quality professional 3D medicine box standing on a clean surface. Realistic shadows, cinematic medical studio lighting, 8k resolution, photorealistic textures."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    for (const part of response.candidates?.[0].content.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Không nhận được dữ liệu hình ảnh từ AI.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

