            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {INITIAL_PROMPTS.map((template, idx) => {
                    const isActive = activeProduct.description === template.prompt;
                    return (
                        <button
                            key={idx}
                            onClick={() => handleSelectTemplate(template.prompt)}
