                <label className="flex items-center gap-2 cursor-pointer bg-slate-100 px-3 py-2 rounded-full border border-slate-200 group">
                    <input type="checkbox" checked={activeProduct.isETC} onChange={(e) => onChange(activeTab, 'isETC', e.target.checked)} className="w-4 h-4 text-emerald-600 accent-emerald-600" />
                    <span className={`text-xs font-black ${activeProduct.isETC ? 'text-red-600' : 'text-slate-500 group-hover:text-slate-700'}`}>ETC</span>
                </label>
            </div>
        </div>

        {/* SECTION 3: IMAGE UPLOAD & AI PROCESSING */}
        <div className="space-y-5">
          <div className="border-2 border-dashed border-slate-300 rounded-2xl p-5 bg-slate-50/50 hover:bg-white hover:border-indigo-400 transition-all group relative">
            <label className="block text-sm font-bold text-slate-700 mb-3 flex justify-between items-center">
              <span className="flex items-center gap-2"><ImageIcon className="w-4 h-4 text-indigo-500" /> ẢNH SẢN PHẨM (GỐC HOẶC LINK)</span>
              {activeProduct.imageBase64 && (
                <button onClick={() => onRemoveImage(activeTab)} className="text-xs text-red-500 hover:text-red-700 font-bold flex items-center gap-1 bg-red-50 px-2 py-1 rounded-md"><Trash2 className="w-3 h-3" /> XÓA</button>
              )}
            </label>

            <input type="file" accept="image/*" ref={fileInputRef} onChange={(e) => e.target.files?.[0] && onImageUpload(activeTab, e.target.files[0])} className="hidden" />

            {imageLoading ? (
                <div className="flex flex-col items-center justify-center py-10 text-indigo-600">
                    <Loader2 className="w-12 h-12 animate-spin mb-3" />
                    <p className="text-sm font-black animate-pulse tracking-widest">AI ĐANG XỬ LÝ ẢNH...</p>
                </div>
            ) : !activeProduct.imageBase64 ? (
              <div className="flex flex-col gap-5">
                  <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer flex flex-col items-center justify-center py-6 text-slate-400 hover:text-indigo-500 group-hover:scale-105 transition-transform">
                    <Upload className="w-10 h-10 mb-2 opacity-30" />
                    <p className="text-sm font-bold">Tải ảnh từ máy tính của bạn</p>
                  </div>
                  <div className="flex items-center gap-3 border-t border-slate-200 pt-4">
                     <LinkIcon className="w-4 h-4 text-slate-400" />
                     <input type="text" placeholder="Dán link ảnh trực tiếp tại đây..." className="flex-1 text-xs border border-slate-200 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" value={imageUrlInput} onChange={(e) => setImageUrlInput(e.target.value)} />
                     <button onClick={handleUrlLoad} disabled={!imageUrlInput.trim() || isUrlLoading} className="text-xs bg-indigo-600 text-white px-5 py-2.5 rounded-lg font-bold disabled:opacity-50 transition-all hover:bg-indigo-700 active:scale-95 shadow-md shadow-indigo-200">DÙNG</button>
                  </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex flex-col md:flex-row items-center gap-5">
                    <div className="w-32 h-32 rounded-xl overflow-hidden border-4 border-white shadow-xl shrink-0 bg-white relative group">
                        <img src={activeProduct.imageBase64} alt="Product" className="w-full h-full object-contain" />
                        <div onClick={() => fileInputRef.current?.click()} className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center transition-opacity cursor-pointer">
                            <Upload className="w-6 h-6 text-white mb-1" />
                            <span className="text-[10px] text-white font-bold">THAY THẾ</span>
                        </div>
                    </div>
                    <div className="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                        <button onClick={() => onAIAction?.('remove_bg')} className="flex items-center justify-center gap-2 px-4 py-3 bg-white border-2 border-indigo-100 text-indigo-700 text-xs font-black rounded-xl hover:bg-indigo-50 transition-all shadow-sm active:scale-95">
                            <Eraser className="w-4 h-4" /> XÓA NỀN AI
                        </button>
                        <button onClick={() => onAIAction?.('make_3d')} className="flex items-center justify-center gap-2 px-4 py-3 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 active:scale-95">
                            <Box className="w-4 h-4" /> TẠO HỘP 3D
                        </button>
                        <button onClick={handleDownloadImage} className="sm:col-span-2 flex items-center justify-center gap-2 px-4 py-3 bg-emerald-50 text-emerald-700 border-2 border-emerald-100 text-xs font-black rounded-xl hover:bg-emerald-100 transition-all active:scale-95">
                            <Download className="w-4 h-4" /> TẢI VỀ MÁY (TÊN: {activeProduct.name || 'SP'})
                        </button>
                    </div>
                </div>
              </div>
            )}
          </div>

          {/* INPUT FIELDS */}
          <div className="grid grid-cols-1 gap-5">
            <div className="relative z-20">
              <label className="block text-sm font-bold text-slate-700 mb-2">TÊN THUỐC (TIÊU ĐỀ CHÍNH)</label>
              <div className="relative">
                <input type="text" value={activeProduct.name} onChange={(e) => handleChange(e, 'name')} onFocus={() => setShowSuggestions(true)} onBlur={() => setTimeout(() => setShowSuggestions(false), 200)} placeholder="VD: Panadol Extra" className="w-full pl-12 pr-4 py-3.5 border-2 border-slate-200 rounded-xl outline-none font-black text-slate-800 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all bg-slate-50/50" />
                <Pill className="w-5 h-5 text-slate-400 absolute left-4 top-4" />
                {showSuggestions && suggestions.length > 0 && (
                    <ul className="absolute z-50 w-full bg-white border-2 border-indigo-100 rounded-xl shadow-2xl mt-2 max-h-60 overflow-y-auto animate-in slide-in-from-top-2 duration-200">
                        {suggestions.map((item, idx) => (
                            <li key={idx} onMouseDown={() => { onApplyLibraryProduct?.(activeTab, item); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-indigo-50 cursor-pointer text-sm border-b border-slate-50 last:border-0 flex justify-between items-center group">
                               <div>
                                  <span className="font-bold text-slate-800 group-hover:text-indigo-700">{item[columnMapping!.name]}</span>
                                  {item[columnMapping!.dosage] && <span className="text-xs text-slate-400 ml-2">[{item[columnMapping!.dosage]}]</span>}
                               </div>
                               <ArrowRight className="w-4 h-4 text-slate-200 group-hover:text-indigo-400" />
                            </li>
                        ))}
                    </ul>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">HÀM LƯỢNG / NỒNG ĐỘ</label>
                <input type="text" value={activeProduct.dosage} onChange={(e) => onChange(activeTab, 'dosage', e.target.value)} placeholder="VD: 500mg" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">CÔNG DỤNG (DÒNG PHỤ)</label>
                <div className="relative">
                  <input type="text" value={activeProduct.usage} onChange={(e) => onChange(activeTab, 'usage', e.target.value)} placeholder="VD: Hạ sốt nhanh, giảm đau" className="w-full pl-11 pr-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
                  <HeartPulse className="w-5 h-5 text-slate-400 absolute left-4 top-3.5" />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">GIÁ NIÊM YẾT</label>
                <input type="text" value={activeProduct.listPrice} onChange={(e) => onChange(activeTab, 'listPrice', e.target.value)} placeholder="200,000 đ" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
              </div>
              <div>
                <label className="block text-sm font-bold text-emerald-700 mb-2 tracking-tighter">GIÁ ĐẶC BIỆT TỪ IDECO</label>
                <div className="relative">
                  <input type="text" value={activeProduct.idecoPrice} onChange={(e) => onChange(activeTab, 'idecoPrice', e.target.value)} placeholder="185,000 đ" className="w-full pl-11 pr-4 py-3 border-2 border-emerald-200 bg-emerald-50 rounded-xl font-black text-emerald-800 outline-none focus:border-emerald-500 shadow-sm" />
                  <DollarSign className="w-5 h-5 text-emerald-600 absolute left-4 top-3.5" />
                </div>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">NHÀ SẢN XUẤT</label>
              <input type="text" value={activeProduct.manufacturer} onChange={(e) => onChange(activeTab, 'manufacturer', e.target.value)} placeholder="VD: DHG Pharma" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                 <FileText className="w-4 h-4 text-indigo-500" /> MÔ TẢ / CHI TIẾT PROMPT
              </label>
              <textarea value={activeProduct.description} onChange={(e) => onChange(activeTab, 'description', e.target.value)} className="w-full p-4 border-2 border-slate-200 rounded-2xl outline-none h-32 resize-none text-sm focus:border-indigo-500 bg-slate-50/50 focus:bg-white shadow-inner leading-relaxed" placeholder="Ghi thêm các yêu cầu đặc biệt về bối cảnh hoặc phong cách tại đây..." />
              <p className="text-[10px] text-slate-400 mt-2 italic">* AI sẽ dựa vào mô tả này để viết prompt chi tiết cho công cụ tạo ảnh.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Submit Button */}
      <div className="p-6 border-t border-slate-100 bg-slate-50 shrink-0">
        <button onClick={onSubmit} disabled={isProcessing} className={`w-full py-4 px-8 rounded-2xl text-white font-black shadow-xl shadow-indigo-100 transition-all flex items-center justify-center gap-3 uppercase tracking-widest ${isProcessing ? 'bg-slate-400' : 'bg-gradient-to-r from-indigo-600 to-blue-600 hover:shadow-indigo-300 active:scale-[0.98]'}`}>
          {isProcessing ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
          {isProcessing ? 'ĐANG TẠO PROMPT...' : 'TẠO 3 PROMPT SẢN PHẨM'}
        </button>
      </div>
    </div>
  );
};

// Simplified Check icon for the component
const Check = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <polyline points="20 6 9 17 4 12"></polyline>
    </svg>
);

import React, { useRef, useState, useMemo } from 'react';
import { ProductData, ExcelMapping } from '../types';
// Add Image as ImageIcon and ArrowRight to imports
import { Pill, DollarSign, Factory, FileText, Tag, Upload, Trash2, HeartPulse, Smartphone, Monitor, Quote, Search, Link as LinkIcon, Download, X, Eraser, Box, Loader2, LayoutGrid, Palette, Image as ImageIcon, ArrowRight } from 'lucide-react';
import { Sparkles } from 'lucide-react';
import { INITIAL_PROMPTS } from '../constants';

interface ProductFormProps {
  products: ProductData[];
  activeTab: number;
  onTabChange: (id: number) => void;
  onChange: (id: number, field: keyof ProductData, value: string | boolean) => void;
  onImageUpload: (id: number, file: File) => void;
  onRemoveImage: (id: number) => void;
  onSubmit: () => void;
  isProcessing: boolean;
  masterLibrary?: any[];
  columnMapping?: ExcelMapping;
  onApplyLibraryProduct?: (id: number, libraryItem: any) => void;
  imageLoading?: boolean;
  onAIAction?: (task: 'remove_bg' | 'make_3d') => void;
}

export const ProductForm: React.FC<ProductFormProps> = ({ 
  products, 
  activeTab, 
  onTabChange, 
  onChange, 
  onImageUpload, 
  onRemoveImage,
  onSubmit, 
  isProcessing,
  masterLibrary = [],
  columnMapping,
  onApplyLibraryProduct,
  imageLoading,
  onAIAction
}) => {

  const activeProduct = products.find(p => p.id === activeTab) || products[0];
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [imageUrlInput, setImageUrlInput] = useState('');
  const [isUrlLoading, setIsUrlLoading] = useState(false);

  const suggestions = useMemo(() => {
    if (!activeProduct.name || !masterLibrary.length || !columnMapping?.name) return [];
    const lowerInput = activeProduct.name.toLowerCase();
    const nameKey = columnMapping.name;
    return masterLibrary
        .filter(item => item[nameKey] && String(item[nameKey]).toLowerCase().includes(lowerInput))
        .slice(0, 5);
  }, [activeProduct.name, masterLibrary, columnMapping]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>, field: keyof ProductData) => {
    onChange(activeTab, field, e.target.value);
    if (field === 'name') setShowSuggestions(true);
  };

  const handleUrlLoad = async () => {
      if (!imageUrlInput.trim()) return;
      setIsUrlLoading(true);
      try {
          const img = new Image();
          img.crossOrigin = "Anonymous";
          img.src = imageUrlInput;
          await new Promise((resolve, reject) => {
              img.onload = resolve;
              img.onerror = () => reject(new Error("CORS error or invalid URL"));
          });
          const canvas = document.createElement('canvas');
          canvas.width = img.naturalWidth;
          canvas.height = img.naturalHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(img, 0, 0);
              const dataURL = canvas.toDataURL('image/png');
              const res = await fetch(dataURL);
              const blob = await res.blob();
              const file = new File([blob], "downloaded_image.png", { type: "image/png" });
              onImageUpload(activeTab, file);
              setImageUrlInput('');
          }
      } catch (e) {
          alert("Lỗi tải ảnh: Trang web gốc chặn tải trực tiếp (CORS). Hãy tải về máy và upload thủ công.");
      } finally {
          setIsUrlLoading(false);
      }
  };

  const handleDownloadImage = () => {
    if (!activeProduct.imageBase64) return;
    const link = document.createElement('a');
    link.href = activeProduct.imageBase64;
    const fileName = activeProduct.name ? activeProduct.name.replace(/[/\\?%*:|"<>]/g, '-') : `product-${activeTab}`;
    link.download = `${fileName}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSelectTemplate = (promptText: string) => {
      onChange(activeTab, 'description', promptText);
  };

  return (
    <div className="bg-white rounded-xl shadow-xl flex flex-col h-full border border-slate-200 overflow-hidden">
      {/* Product Tabs */}
      <div className="flex bg-slate-100 border-b border-slate-200 overflow-hidden shrink-0">
        {products.map((p) => (
          <button 
            key={p.id} 
            onClick={() => onTabChange(p.id)} 
            className={`flex-1 py-4 text-sm font-bold transition-all flex items-center justify-center gap-2 border-r border-slate-200 last:border-r-0 ${activeTab === p.id ? 'bg-white text-indigo-700 border-t-4 border-t-indigo-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200 hover:text-slate-700'}`}
          >
            <div className={`w-2 h-2 rounded-full ${activeTab === p.id ? 'bg-indigo-600' : 'bg-slate-300'}`}></div>
            SẢN PHẨM {p.id}
          </button>
        ))}
      </div>

      <div className="p-6 md:p-8 flex-1 overflow-y-auto custom-scrollbar">
        {/* SECTION 1: TEMPLATE SELECTION - HIGH PRIORITY */}
        <div className="mb-8 p-5 bg-gradient-to-br from-indigo-50 to-slate-50 rounded-2xl border-2 border-indigo-100 shadow-sm">
            <h3 className="text-sm font-black text-indigo-900 uppercase tracking-widest mb-4 flex items-center gap-2">
                <Palette className="w-5 h-5" /> CHỌN PHONG CÁCH POSTER (TEMPLATE)
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {INITIAL_PROMPTS.map((template, idx) => {
                    const isActive = activeProduct.description === template.prompt;
                    return (
                        <button
                            key={idx}
                            onClick={() => handleSelectTemplate(template.prompt)}
                            className={`relative text-left p-4 rounded-xl border-2 transition-all group overflow-hidden ${isActive ? 'bg-white border-indigo-500 ring-4 ring-indigo-100 shadow-md' : 'bg-white/80 border-slate-200 hover:border-indigo-300 hover:bg-white'}`}
                        >
                            {isActive && (
                                <div className="absolute top-0 right-0 p-1 bg-indigo-500 text-white rounded-bl-lg">
                                    <Check className="w-3 h-3" />
                                </div>
                            )}
                            <div className={`text-xs font-black mb-2 uppercase tracking-tighter ${isActive ? 'text-indigo-700' : 'text-slate-600'}`}>
                                {template.name}
                            </div>
                            <div className="text-[10px] text-slate-500 line-clamp-3 leading-relaxed">
                                {template.prompt}
                            </div>
                            <div className="mt-3 flex flex-wrap gap-1">
                                {template.keywords.slice(0, 2).map(kw => (
                                    <span key={kw} className="text-[9px] px-1.5 py-0.5 bg-slate-100 rounded text-slate-500 font-medium">#{kw}</span>
                                ))}
                            </div>
                        </button>
                    );
                })}
            </div>
            {activeProduct.description && (
                <button 
                    onClick={() => onChange(activeTab, 'description', '')}
                    className="mt-4 text-[10px] font-bold text-red-400 hover:text-red-600 uppercase flex items-center gap-1 ml-auto"
                >
                    <Trash2 className="w-3 h-3" /> Xóa mẫu đã chọn
                </button>
            )}
        </div>

        {/* SECTION 2: PRODUCT INFO HEADER */}
        <div className="flex flex-wrap items-center justify-between mb-6 gap-3 pt-2 border-t border-slate-100">
            <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Pill className="w-6 h-6 text-emerald-600" /> THÔNG TIN CHI TIẾT
            </h2>
            <div className="flex items-center gap-3">
                 <div className="bg-slate-100 p-1 rounded-lg flex border border-slate-200">
                    <button onClick={() => onChange(activeTab, 'aspectRatio', 'vertical')} className={`px-4 py-1.5 text-xs font-black rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'vertical' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}><Smartphone className="w-3.5 h-3.5" /> DỌC</button>
                    <button onClick={() => onChange(activeTab, 'aspectRatio', 'horizontal')} className={`px-4 py-1.5 text-xs font-black rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'horizontal' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}><Monitor className="w-3.5 h-3.5" /> NGANG</button>
                </div>
                <label className="flex items-center gap-2 cursor-pointer bg-slate-100 px-3 py-2 rounded-full border border-slate-200 group">
                    <input type="checkbox" checked={activeProduct.isETC} onChange={(e) => onChange(activeTab, 'isETC', e.target.checked)} className="w-4 h-4 text-emerald-600 accent-emerald-600" />
                    <span className={`text-xs font-black ${activeProduct.isETC ? 'text-red-600' : 'text-slate-500 group-hover:text-slate-700'}`}>ETC</span>
                </label>
            </div>
        </div>

        {/* SECTION 3: IMAGE UPLOAD & AI PROCESSING */}
        <div className="space-y-5">
          <div className="border-2 border-dashed border-slate-300 rounded-2xl p-5 bg-slate-50/50 hover:bg-white hover:border-indigo-400 transition-all group relative">
            <label className="block text-sm font-bold text-slate-700 mb-3 flex justify-between items-center">
              <span className="flex items-center gap-2"><ImageIcon className="w-4 h-4 text-indigo-500" /> ẢNH SẢN PHẨM (GỐC HOẶC LINK)</span>
              {activeProduct.imageBase64 && (
                <button onClick={() => onRemoveImage(activeTab)} className="text-xs text-red-500 hover:text-red-700 font-bold flex items-center gap-1 bg-red-50 px-2 py-1 rounded-md"><Trash2 className="w-3 h-3" /> XÓA</button>
              )}
            </label>

            <input type="file" accept="image/*" ref={fileInputRef} onChange={(e) => e.target.files?.[0] && onImageUpload(activeTab, e.target.files[0])} className="hidden" />

            {imageLoading ? (
                <div className="flex flex-col items-center justify-center py-10 text-indigo-600">
                    <Loader2 className="w-12 h-12 animate-spin mb-3" />
                    <p className="text-sm font-black animate-pulse tracking-widest">AI ĐANG XỬ LÝ ẢNH...</p>
                </div>
            ) : !activeProduct.imageBase64 ? (
              <div className="flex flex-col gap-5">
                  <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer flex flex-col items-center justify-center py-6 text-slate-400 hover:text-indigo-500 group-hover:scale-105 transition-transform">
                    <Upload className="w-10 h-10 mb-2 opacity-30" />
                    <p className="text-sm font-bold">Tải ảnh từ máy tính của bạn</p>
                  </div>
                  <div className="flex items-center gap-3 border-t border-slate-200 pt-4">
                     <LinkIcon className="w-4 h-4 text-slate-400" />
                     <input type="text" placeholder="Dán link ảnh trực tiếp tại đây..." className="flex-1 text-xs border border-slate-200 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500" value={imageUrlInput} onChange={(e) => setImageUrlInput(e.target.value)} />
                     <button onClick={handleUrlLoad} disabled={!imageUrlInput.trim() || isUrlLoading} className="text-xs bg-indigo-600 text-white px-5 py-2.5 rounded-lg font-bold disabled:opacity-50 transition-all hover:bg-indigo-700 active:scale-95 shadow-md shadow-indigo-200">DÙNG</button>
                  </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex flex-col md:flex-row items-center gap-5">
                    <div className="w-32 h-32 rounded-xl overflow-hidden border-4 border-white shadow-xl shrink-0 bg-white relative group">
                        <img src={activeProduct.imageBase64} alt="Product" className="w-full h-full object-contain" />
                        <div onClick={() => fileInputRef.current?.click()} className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center transition-opacity cursor-pointer">
                            <Upload className="w-6 h-6 text-white mb-1" />
                            <span className="text-[10px] text-white font-bold">THAY THẾ</span>
                        </div>
                    </div>
                    <div className="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-3 w-full">
                        <button onClick={() => onAIAction?.('remove_bg')} className="flex items-center justify-center gap-2 px-4 py-3 bg-white border-2 border-indigo-100 text-indigo-700 text-xs font-black rounded-xl hover:bg-indigo-50 transition-all shadow-sm active:scale-95">
                            <Eraser className="w-4 h-4" /> XÓA NỀN AI
                        </button>
                        <button onClick={() => onAIAction?.('make_3d')} className="flex items-center justify-center gap-2 px-4 py-3 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 active:scale-95">
                            <Box className="w-4 h-4" /> TẠO HỘP 3D
                        </button>
                        <button onClick={handleDownloadImage} className="sm:col-span-2 flex items-center justify-center gap-2 px-4 py-3 bg-emerald-50 text-emerald-700 border-2 border-emerald-100 text-xs font-black rounded-xl hover:bg-emerald-100 transition-all active:scale-95">
                            <Download className="w-4 h-4" /> TẢI VỀ MÁY (TÊN: {activeProduct.name || 'SP'})
                        </button>
                    </div>
                </div>
              </div>
            )}
          </div>

          {/* INPUT FIELDS */}
          <div className="grid grid-cols-1 gap-5">
            <div className="relative z-20">
              <label className="block text-sm font-bold text-slate-700 mb-2">TÊN THUỐC (TIÊU ĐỀ CHÍNH)</label>
              <div className="relative">
                <input type="text" value={activeProduct.name} onChange={(e) => handleChange(e, 'name')} onFocus={() => setShowSuggestions(true)} onBlur={() => setTimeout(() => setShowSuggestions(false), 200)} placeholder="VD: Panadol Extra" className="w-full pl-12 pr-4 py-3.5 border-2 border-slate-200 rounded-xl outline-none font-black text-slate-800 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all bg-slate-50/50" />
                <Pill className="w-5 h-5 text-slate-400 absolute left-4 top-4" />
                {showSuggestions && suggestions.length > 0 && (
                    <ul className="absolute z-50 w-full bg-white border-2 border-indigo-100 rounded-xl shadow-2xl mt-2 max-h-60 overflow-y-auto animate-in slide-in-from-top-2 duration-200">
                        {suggestions.map((item, idx) => (
                            <li key={idx} onMouseDown={() => { onApplyLibraryProduct?.(activeTab, item); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-indigo-50 cursor-pointer text-sm border-b border-slate-50 last:border-0 flex justify-between items-center group">
                               <div>
                                  <span className="font-bold text-slate-800 group-hover:text-indigo-700">{item[columnMapping!.name]}</span>
                                  {item[columnMapping!.dosage] && <span className="text-xs text-slate-400 ml-2">[{item[columnMapping!.dosage]}]</span>}
                               </div>
                               <ArrowRight className="w-4 h-4 text-slate-200 group-hover:text-indigo-400" />
                            </li>
                        ))}
                    </ul>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">HÀM LƯỢNG / NỒNG ĐỘ</label>
                <input type="text" value={activeProduct.dosage} onChange={(e) => onChange(activeTab, 'dosage', e.target.value)} placeholder="VD: 500mg" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">CÔNG DỤNG (DÒNG PHỤ)</label>
                <div className="relative">
                  <input type="text" value={activeProduct.usage} onChange={(e) => onChange(activeTab, 'usage', e.target.value)} placeholder="VD: Hạ sốt nhanh, giảm đau" className="w-full pl-11 pr-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
                  <HeartPulse className="w-5 h-5 text-slate-400 absolute left-4 top-3.5" />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">GIÁ NIÊM YẾT</label>
                <input type="text" value={activeProduct.listPrice} onChange={(e) => onChange(activeTab, 'listPrice', e.target.value)} placeholder="200,000 đ" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
              </div>
              <div>
                <label className="block text-sm font-bold text-emerald-700 mb-2 tracking-tighter">GIÁ ĐẶC BIỆT TỪ IDECO</label>
                <div className="relative">
                  <input type="text" value={activeProduct.idecoPrice} onChange={(e) => onChange(activeTab, 'idecoPrice', e.target.value)} placeholder="185,000 đ" className="w-full pl-11 pr-4 py-3 border-2 border-emerald-200 bg-emerald-50 rounded-xl font-black text-emerald-800 outline-none focus:border-emerald-500 shadow-sm" />
                  <DollarSign className="w-5 h-5 text-emerald-600 absolute left-4 top-3.5" />
                </div>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">NHÀ SẢN XUẤT</label>
              <input type="text" value={activeProduct.manufacturer} onChange={(e) => onChange(activeTab, 'manufacturer', e.target.value)} placeholder="VD: DHG Pharma" className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 focus:bg-white transition-all bg-slate-50/50 font-medium" />
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                 <FileText className="w-4 h-4 text-indigo-500" /> MÔ TẢ / CHI TIẾT PROMPT
              </label>
              <textarea value={activeProduct.description} onChange={(e) => onChange(activeTab, 'description', e.target.value)} className="w-full p-4 border-2 border-slate-200 rounded-2xl outline-none h-32 resize-none text-sm focus:border-indigo-500 bg-slate-50/50 focus:bg-white shadow-inner leading-relaxed" placeholder="Ghi thêm các yêu cầu đặc biệt về bối cảnh hoặc phong cách tại đây..." />
              <p className="text-[10px] text-slate-400 mt-2 italic">* AI sẽ dựa vào mô tả này để viết prompt chi tiết cho công cụ tạo ảnh.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Submit Button */}
      <div className="p-6 border-t border-slate-100 bg-slate-50 shrink-0">
        <button onClick={onSubmit} disabled={isProcessing} className={`w-full py-4 px-8 rounded-2xl text-white font-black shadow-xl shadow-indigo-100 transition-all flex items-center justify-center gap-3 uppercase tracking-widest ${isProcessing ? 'bg-slate-400' : 'bg-gradient-to-r from-indigo-600 to-blue-600 hover:shadow-indigo-300 active:scale-[0.98]'}`}>
          {isProcessing ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
          {isProcessing ? 'ĐANG TẠO PROMPT...' : 'TẠO 3 PROMPT SẢN PHẨM'}
        </button>
      </div>
    </div>
  );
};

