                <input type="text" value={activeProduct.idecoPrice} onChange={(e) => onChange(activeTab, 'idecoPrice', e.target.value)} placeholder="185,000 đ" className="w-full pl-11 pr-4 py-3 border-2 border-emerald-200 bg-emerald-50 rounded-xl font-black text-emerald-800 outline-none shadow-sm" />
                <DollarSign className="w-5 h-5 text-emerald-600 absolute left-4 top-3.5" />
