      {/* FOOTER ACTION */}
      <div className="p-6 border-t border-slate-100 bg-slate-50 shrink-0">
        <button onClick={onSubmit} disabled={isProcessing} className={`w-full py-4 px-8 rounded-2xl text-white font-black shadow-xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest ${isProcessing ? 'bg-slate-400' : 'bg-gradient-to-r from-indigo-600 to-blue-600 hover:shadow-indigo-300 active:scale-[0.98]'}`}>
          {isProcessing ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
          {isProcessing ? 'Đang tạo dữ liệu...' : 'Tạo 3 Prompt Sản Phẩm'}
        </button>
