                const loadedElements = await Promise.all(initials.map(async el => {
                    if (el.type === 'image' && el.src && !el.imageElement) {
                        return new Promise((resolve) => {
                            const img = new Image();
                            img.onload = () => resolve({ ...el, imageElement: img });
