            }

            // --- RESIZE LOGIC ---
            const resizeText = (textEl: TextProperties): TextProperties => {
                // FIX: Cast initialElement correctly to TextProperties to avoid union type access errors.
                const initTextEl = initialElement as TextProperties;
                if (isShiftHeld) { // Proportional
                    const metrics = getElementMetrics(initTextEl);
                    const center = { x: metrics.centerX, y: metrics.centerY };
                    const initialDist = Math.hypot(initialMousePos.x - center.x, initialMousePos.y - center.y);
                    const currentDist = Math.hypot(mousePos.x - center.x, mousePos.y - center.y);
                    if (initialDist === 0) return textEl;
                    const scale = currentDist / initialDist;
                    const newWidth = Math.max(20, initTextEl.width * scale);
                    const newFontSize = Math.max(8, initTextEl.fontSize * scale);
                    const newMetrics = getElementMetrics({ ...initTextEl, width: newWidth, fontSize: newFontSize });
                    return { ...textEl, width: newWidth, fontSize: newFontSize, x: center.x - newWidth / 2, y: center.y - newMetrics.height / 2 };
                } else { // Freeform
                    let newWidth = textEl.width;
                    if (type.includes('right')) newWidth = Math.max(20, initTextEl.width + localDx);
                    if (type.includes('left')) newWidth = Math.max(20, initTextEl.width - localDx);

                    const dw = newWidth - initTextEl.width;
                    const initialMetrics = getElementMetrics(initTextEl);
                    let shiftX = 0;
                    if (type.includes('right')) shiftX += dw / 2; if (type.includes('left')) shiftX -= dw / 2;

                    const rotatedShiftX = shiftX * cos; const rotatedShiftY = shiftX * sin;
                    const oldCenter = { x: initialMetrics.centerX, y: initialMetrics.centerY };
                    const newCenter = { x: oldCenter.x + rotatedShiftX, y: oldCenter.y + rotatedShiftY };

                    return { ...textEl, width: newWidth, x: newCenter.x - newWidth / 2, y: newCenter.y - initialMetrics.height / 2 };
                }
            };

            const resizeShape = (shapeEl: ImageProperties | BannerProperties): ImageProperties | BannerProperties => {
                // FIX: Cast initialElement to the common properties shared by ImageProperties and BannerProperties.
                const initShapeEl = initialElement as (ImageProperties | BannerProperties);
                let newWidth = initShapeEl.width; let newHeight = initShapeEl.height;
                if (type.includes('right')) newWidth = Math.max(20, initShapeEl.width + localDx);
                if (type.includes('left')) newWidth = Math.max(20, initShapeEl.width - localDx);
                if (type.includes('bottom')) newHeight = Math.max(20, initShapeEl.height + localDy);
                if (type.includes('top')) newHeight = Math.max(20, initShapeEl.height - localDy);

                if (isShiftHeld && shapeEl.type === 'banner') {
                     const initialAspectRatio = initShapeEl.width / initShapeEl.height;
                     if (type.includes('left') || type.includes('right')) newHeight = newWidth / initialAspectRatio;
                     else newWidth = newHeight * initialAspectRatio;
                } else if (shapeEl.type === 'image') {
                    if (type.includes('left') || type.includes('right')) newHeight = newWidth / shapeEl.aspectRatio;
                    else newWidth = newHeight * shapeEl.aspectRatio;
                }

                const dw = newWidth - initShapeEl.width; const dh = newHeight - initShapeEl.height;
                let shiftX = 0; let shiftY = 0;
                if (type.includes('right')) shiftX += dw / 2; if (type.includes('left')) shiftX -= dw / 2;
                if (type.includes('bottom')) shiftY += dh / 2; if (type.includes('top')) shiftY -= dh / 2;
                const rotatedShiftX = shiftX * cos - shiftY * sin; const rotatedShiftY = shiftX * sin + shiftY * cos;
                const oldCenter = { x: initShapeEl.x + initShapeEl.width / 2, y: initShapeEl.y + initShapeEl.height / 2 };
                const newCenter = { x: oldCenter.x + rotatedShiftX, y: oldCenter.y + rotatedShiftY };
                return { ...shapeEl, width: newWidth, height: newHeight, x: newCenter.x - newWidth / 2, y: newCenter.y - newHeight / 2 } as (ImageProperties | BannerProperties);
            };

